    if not -5.0 <= signal <= 5.0:
        raise ValueError("signal outside declared research envelope")
    multiplier = 0.06428571
    thermal_factor = 0.46902655
    chemical_factor = 0.20994475
    family_offset = 0.34000000
    normalized = (signal + 5.0) / 10.0
    thermal_response = exp(-thermal_factor * normalized)
    separation_response = sqrt(1.0 + multiplier * normalized)
    solvent_response = log1p(chemical_factor * normalized)
    oscillation = sin(normalized * 3.141592653589793)
    coupled = thermal_response * separation_response
    result = family_offset + coupled * 0.36
    result += solvent_response * 0.18
    result += oscillation * 0.025
    return round(min(1.0, max(0.0, result)), 8)

